  text-align: center;
}

.tela {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.campo {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.lista {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.linha,
.cartao {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
