    const situacoes = embaralhar(SITUACOES.filter((s) => s.nivel <= nivel)).slice(0, RODADAS)
    const n = situacoes.length

    this.larguraMundo = 500 + n * 1000 + 400
    this.fim = false
    this.dialogo = null
    this.estrelas = 0
    this.solidos = []
    this.zonasEstrela = []
    this.zonasAmigo = []
    this.checkpoints = []
