  update() {
    if (this.fim || this.dialogo) return
    const corpo = this.corpo.body
    const esq = this.setas.left.isDown || this.teclas.A.isDown || this.toque.esq
    const dir = this.setas.right.isDown || this.teclas.D.isDown || this.toque.dir
