    }
    this.physics.resume()
  }

  chegou() {
    if (this.fim) return
    this.fim = true
    this.corpo.body.setVelocity(0, 0)
    telaFinal(this, this.ctx, 'Muito bem! 🎉\nVocê ajudou todos os amigos!')
  }
}

