import puppeteer from 'puppeteer-core'
const b = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: true })
const p = await b.newPage()
await p.setViewport({ width: 1000, height: 700 })
const erros = []
p.on('pageerror', (e) => erros.push('pageerror: ' + e.message))
p.on('console', (m) => { if (m.type() === 'error') erros.push('console: ' + m.text()) })
const esperar = (ms) => new Promise((r) => setTimeout(r, ms))
const clicar = async (txt) => { const [h] = await p.$$(`xpath/.//button[contains(., "${txt}")]`); if (!h) throw new Error('sem botão ' + txt); await h.click() }
const cena = () => p.evaluate(() => {
  const s = window.__phaser.scene.scenes[0]
  return { x: Math.round(s.corpo.x), y: Math.round(s.corpo.y), dialogo: !!s.dialogo, fim: s.fim, estrelas: s.estrelas,
    amigos: s.zonasAmigo.map((z) => z.amigo.resolvido), mundo: s.larguraMundo }
})

await p.goto('http://localhost:5173/')
await p.evaluate(() => localStorage.clear())
await p.reload()
await clicar('Preencher exemplo'); await clicar('Continuar'); await clicar('Trem')
// no exemplo: Plataforma é o 3º cartão
const botoes = await p.$$('.cartao button')
await botoes[2].click()
await esperar(1200)
await p.screenshot({ path: 'plat0.png' })

await p.keyboard.down('ArrowRight')
let ultimo = 0, quedas = 0, tentativa = 0
for (let t = 0; t < 400; t++) {
  const e = await cena()
  if (e.fim) break
  if (e.dialogo) {
    await p.keyboard.up('ArrowRight')
    if (t % 3 === 0) await p.screenshot({ path: `dialogo${tentativa}.png` })
    await p.keyboard.press(String((tentativa++ % 3) + 1))
    await esperar(300)
    if (!(await cena()).dialogo) await p.keyboard.down('ArrowRight')
    continue
  }
  await p.keyboard.down('ArrowRight')
  await p.keyboard.down('Space')
  await esperar(120)
