 *
 * @param {number} width - The width of this Game Object.
 * @param {number} height - The height of this Game Object.
 *
 * @return {this} This Game Object instance.
 */
setSize: function (width, height)
{
    this.width = width;
    this.height = height;

    this.geom.setSize(width, height);

