import Phaser from 'phaser'
import { HISTORIAS } from '../data/historias.js'
import { FONTE, RAIO, botao, caixaTexto, criarHud, telaFinal, embaralhar } from './ui.js'
import { sortear } from '../variedade.js'

// Jogo calmo e sem tempo: a criança escolhe o que o personagem faz e vê a consequência.
export default class HistoriaEscolhas extends Phaser.Scene {
  constructor() {
    super('HistoriaEscolhas')
  }

  init() {
    this.ctx = this.registry.get('ctx')
  }

  create() {
    const { hiperfoco, nivel } = this.ctx
    this.cameras.main.setBackgroundColor(hiperfoco.cor)
    // não repete a história até a criança ter visto todas as do nível
    this.historia = sortear(
      `historia:${this.ctx.aluno}`,
      HISTORIAS.filter((h) => h.nivel <= nivel),
      1,
      (h) => h.titulo,
    )[0]
    this.passo = 0
    this.botoes = []

    this.hud = criarHud(this, this.ctx)
    caixaTexto(
      this,
      400,
      68,
      this.historia.titulo,
      { fontSize: '22px', color: '#ffe9a8' },
      { px: 16, py: 5, alpha: 0.35 },
    )
    // painel de leitura atrás da história e da consequência
    this.add.rectangle(440, 175, 720, 150, 0x000000, 0.25).setRounded(RAIO + 4)
    this.add.text(60, 125, hiperfoco.personagem, { fontFamily: FONTE, fontSize: '64px' }).setOrigin(0.5)
    this.texto = this.add
      .text(130, 100, '', { fontFamily: FONTE, fontSize: '24px', color: '#ffffff', wordWrap: { width: 620 } })
    this.retorno = this.add
      .text(130, 205, '', { fontFamily: FONTE, fontSize: '22px', color: '#ffe9a8', wordWrap: { width: 620 } })

    this.mostrarPasso()
  }

  trocar(texto) {
    const frase = texto.replaceAll('{p}', this.ctx.hiperfoco.personagemNome)
    return frase[0].toUpperCase() + frase.slice(1)
  }

  mostrarPasso() {
    const passo = this.historia.passos[this.passo]
    this.travado = false
    this.retorno.setText('')
    this.texto.setText(this.trocar(passo.texto))
    this.botoes.forEach((b) => b.destruir())
    this.botoes = embaralhar(passo.escolhas).map((escolha, i) => {
      const b = botao(this, 400, 295 + i * 62, 640, 50, escolha.texto, () => this.escolher(b, escolha))
      return b
    })
  }

  escolher(b, escolha) {
    if (this.travado) return
    this.retorno.setText(this.trocar(escolha.consequencia))
    if (!escolha.certo) {
      this.hud.erro()
      return b.desativar()
    }

    this.travado = true
    this.botoes.forEach((x) => x.desativar())
    this.hud.acerto()
    this.time.delayedCall(2200, () => {
      this.passo++
      if (this.passo >= this.historia.passos.length) this.terminar()
      else this.mostrarPasso()
    })
  }

  terminar() {
    telaFinal(this, this.ctx, `${this.trocar(this.historia.final)}\n🎉`)
  }
}

// Fonte de jogo (Fredoka, carregada em main.jsx). Para trocar, mude só esta linha e o import.
export const FONTE = 'Fredoka, "Segoe UI", sans-serif'
export const RAIO = 14 // arredondamento das caixas

// Texto dentro de uma caixa de cantos arredondados (o Phaser só desenha fundo quadrado).
// Com texto vazio a caixa some.
export function caixaTexto(scene, x, y, texto, estilo = {}, opcoes = {}) {
  const { px = 14, py = 8, cor = 0x000000, alpha = 0.55, depth = 0, fixo = false } = opcoes
  const t = scene.add
    .text(x, y, texto, { fontFamily: FONTE, fontStyle: 'bold', ...estilo })
    .setOrigin(0.5)
    .setDepth(depth + 1)
  const f = scene.add.rectangle(x, y, 10, 10, cor, alpha).setRounded(RAIO).setDepth(depth)
  if (fixo) {
    t.setScrollFactor(0)
    f.setScrollFactor(0)
  }
  const ajustar = () => {
    f.setVisible(t.text !== '')
    f.setSize(t.width + px * 2, t.height + py * 2)
  }
  ajustar()
  return {
    t,
    f,
    setText(s) {
      t.setText(s)
      ajustar()
      return this
    },
    setDepth(d) {
      f.setDepth(d)
      t.setDepth(d + 1)
      return this
    },
    destroy() {
      f.destroy()
      t.destroy()
    },
  }
}

// Componentes comuns às cenas: botão, HUD com a barra do próximo item e tela final.
export function botao(scene, x, y, w, h, texto, aoClicar, cor = 0x2f6fed) {
  const r = scene.add
    .rectangle(x, y, w, h, cor)
    .setRounded(RAIO)
    .setStrokeStyle(3, 0xffffff)
    .setInteractive({ useHandCursor: true })
    .setScrollFactor(0)
  const t = scene.add
    .text(x, y, texto, {
      fontFamily: FONTE,
      fontStyle: 'bold',
      fontSize: '20px',
      color: '#ffffff',
      align: 'center',
      wordWrap: { width: w - 16 },
    })
    .setOrigin(0.5)
    .setScrollFactor(0)
  r.on('pointerdown', aoClicar)
  return {
    r,
    t,
    desativar() {
      r.disableInteractive()
      r.setAlpha(0.4)
      t.setAlpha(0.5)
    },
    destruir() {
      r.destroy()
      t.destroy()
    },
  }
}

export function criarHud(scene, ctx) {
  const larguraBarra = 220
  // fixo na tela (scrollFactor 0) e acima do cenário, para cenas com câmera que rola
  const fixo = (o) => o.setScrollFactor(0).setDepth(40)
  // painel da pontuação (próximo item + barra) com cantos arredondados
  fixo(scene.add.rectangle(8, 4, 264, 52, 0x000000, 0.4).setOrigin(0, 0).setRounded(RAIO)).setDepth(39)
  const rotulo = fixo(
    scene.add.text(20, 8, '', {
      fontFamily: FONTE,
      fontStyle: 'bold',
      fontSize: '18px',
      color: '#ffffff',
    }),
  )
  fixo(scene.add.rectangle(20, 40, larguraBarra, 10, 0xffffff, 0.25).setOrigin(0, 0.5).setRounded(5))
  const barra = fixo(scene.add.rectangle(20, 40, 10, 10, 0xffd447).setOrigin(0, 0.5).setRounded(5))
  const sair = botao(scene, 740, 26, 90, 34, 'Sair', () => ctx.sair(), 0x555555)
  sair.r.setDepth(40)
  sair.t.setDepth(41)

  function atualizar(e) {
    if (e.proximo) {
      rotulo.setText(`Próximo: ${e.proximo.emoji} ${e.proximo.nome}`)
      const pct = (e.total - e.anterior) / (e.limite - e.anterior)
      barra.setSize(Math.max(10, larguraBarra * pct), 10)
    } else {
      rotulo.setText('Coleção completa! 🎉')
      barra.setSize(larguraBarra, 10)
    }
    return e
  }

  function mostrarDesbloqueio(item) {
    const aviso = caixaTexto(
      scene,
      400,
      225,
      `Novo item!\n${item.emoji}\n${item.nome}`,
      { fontSize: '36px', color: '#ffffff', align: 'center' },
      { px: 28, py: 18, alpha: 0.85, depth: 45, fixo: true },
    )
    if (ctx.efeitos) {
      aviso.f.setScale(0.2)
      aviso.t.setScale(0.2)
      scene.tweens.add({ targets: [aviso.f, aviso.t], scale: 1, duration: 350, ease: 'Back.Out' })
    }
    scene.time.delayedCall(2200, () => aviso.destroy())
  }

  atualizar(ctx.estado())

  return {
    // acerto avança a coleção e entra no desempenho; erro só entra no desempenho
    acerto() {
      ctx.registrarTentativa(true)
      const e = atualizar(ctx.registrarAcerto())
      if (e.novoItem) mostrarDesbloqueio(e.novoItem)
    },
    erro() {
      ctx.registrarTentativa(false)
    },
  }
}

export function telaFinal(scene, ctx, mensagem) {
  scene.add.rectangle(400, 225, 800, 450, 0x000000, 0.7).setScrollFactor(0).setDepth(50)
  caixaTexto(
    scene,
    400,
    150,
    mensagem,
    { fontSize: '34px', color: '#ffffff', align: 'center' },
    { px: 32, py: 16, alpha: 0.5, depth: 51, fixo: true },
  )
  const a = botao(scene, 280, 280, 220, 60, 'Jogar de novo', () => scene.scene.restart(), 0x2e9e5b)
  const b = botao(scene, 520, 280, 220, 60, 'Voltar ao menu', () => ctx.sair(), 0x555555)
  for (const o of [a, b]) {
    o.r.setDepth(53)
    o.t.setDepth(54)
  }
}

export function embaralhar(lista) {
  const copia = [...lista]
  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[copia[i], copia[j]] = [copia[j], copia[i]]
  }
  return copia
}

