import puppeteer from 'puppeteer-core'
const b = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: true })
const p = await b.newPage()
await p.setViewport({ width: 1000, height: 700 })
const erros = []
p.on('pageerror', (e) => erros.push('pageerror: ' + e.message))
p.on('console', (m) => { if (m.type() === 'error') erros.push('console: ' + m.text()) })
const esperar = (ms) => new Promise((r) => setTimeout(r, ms))
const clicar = async (txt) => { const [h] = await p.$$(`xpath/.//button[contains(., "${txt}")]`); if (!h) throw new Error('sem botão ' + txt); await h.click() }
const cena = (fn, ...args) => p.evaluate(fn, ...args)
const canvasBox = async () => { const c = await p.$('canvas'); return c.boundingBox() }
const paraPagina = async (x, y) => { const bb = await canvasBox(); return { x: bb.x + (x / 800) * bb.width, y: bb.y + (y / 450) * bb.height } }

await p.goto('http://localhost:5173/')
await p.evaluate(() => localStorage.clear())
await p.reload()
await p.type('input', 'Teste')
await clicar('Preencher exemplo'); await clicar('Continuar'); await clicar('Trem')
const titulos = await p.$$eval('.cartao h3', (hs) => hs.map((h) => h.innerText))
console.log('jogos listados:', titulos)
const abrir = async (nome) => {
  const i = titulos.findIndex((t) => t.includes(nome))
  const bs = await p.$$('.cartao button'); await bs[i].click(); await esperar(1300)
}
const sair = async () => { const bb = await canvasBox(); await p.mouse.click(bb.x + bb.width * 0.925, bb.y + bb.height * 0.058); await esperar(400) }

// ---------- Cuidar do amigo ----------
await abrir('Cuidar')
let ordem = []
for (let r = 0; r < 5; r++) {
  const info = await cena(() => {
    const s = window.__phaser.scene.scenes[0]
    return { fim: s.rodada >= s.rodadas.length, texto: s.situacao.texto,
      itens: s.itens.map((i) => ({ id: i.id, x: i.casa.x, y: i.casa.y, certo: s.situacao.certos.includes(i.id) })) }
  })
  ordem.push(info.texto)
  const errado = info.itens.find((i) => !i.certo)
  const certo = info.itens.find((i) => i.certo)
  // 1) toca num item errado (não deve avançar a rodada)
  let pt = await paraPagina(errado.x, errado.y)
  await p.mouse.click(pt.x, pt.y); await esperar(1500)
  const rodadaAposErro = await cena(() => window.__phaser.scene.scenes[0].rodada)
  if (rodadaAposErro !== r) console.log('ERRO: rodada avançou com item errado', r, rodadaAposErro)
  // 2) arrasta o item certo até o amigo
  pt = await paraPagina(certo.x, certo.y)
  const amigo = await paraPagina(400, 255)
  await p.mouse.move(pt.x, pt.y); await p.mouse.down()
  for (let k = 1; k <= 10; k++) { await p.mouse.move(pt.x + ((amigo.x - pt.x) * k) / 10, pt.y + ((amigo.y - pt.y) * k) / 10); await esperar(20) }
  await p.mouse.up()
  await esperar(r === 0 ? 400 : 2100)
  if (r === 0) await p.screenshot({ path: 'c_cuidar.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
  if (r === 0) await esperar(1700)
}
await esperar(800)
console.log('cuidar: telas distintas =', new Set(ordem).size, '| terminou:', await cena(() => window.__phaser.scene.scenes[0].rodada))
await p.screenshot({ path: 'c_cuidar_fim.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
const tentativas = await cena(() => JSON.parse(localStorage.getItem('dopamine-desempenho-v1')).filter((t) => t.jogo === 'cuidar-amigo'))
console.log('tentativas registradas em cuidar:', tentativas.length, 'acertos:', tentativas.filter((t) => t.ok).length, 'erros:', tentativas.filter((t) => !t.ok).length)
await sair()

// ---------- Chuva de emoções ----------
await abrir('Chuva')
const ritmo = await cena(() => { const s = window.__phaser.scene.scenes[0]; const a = [s.intervalo(), s.velocidadeQueda()]; s.acertos = 10; const b = [s.intervalo(), s.velocidadeQueda()]; s.acertos = 0; return { inicio: a, apos10: b } })
console.log('ritmo (intervalo ms, queda px/s):', JSON.stringify(ritmo))
let t0 = Date.now(), maxItens = 0, fim = false
while (Date.now() - t0 < 120000 && !fim) {
  const e = await cena(() => {
    const s = window.__phaser.scene.scenes[0]
    if (s.fim) return { fim: true }
    const alvo = s.itens.filter((i) => !i.bonus && i.emocao === s.alvo).sort((a, b) => b.obj.y - a.obj.y)[0]
    if (alvo) s.jogador.x = alvo.obj.x
    return { fim: false, itens: s.itens.length, acertos: s.acertos, combo: s.combo }
  })
  fim = e.fim
  maxItens = Math.max(maxItens, e.itens ?? 0)
  await esperar(60)
}
console.log('chuva: terminou?', fim, '| máx. de rostos ao mesmo tempo:', maxItens, '| tempo (s):', Math.round((Date.now() - t0) / 1000))
await p.screenshot({ path: 'c_chuva_fim.png', clip: { x: 60, y: 80, width: 880, height: 500 } })
console.log('erros:', erros)
await b.close()

