import puppeteer from 'puppeteer-core'
const b = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: true })
const p = await b.newPage()
await p.setViewport({ width: 1200, height: 900 })
const erros = []
p.on('pageerror', (e) => erros.push('pageerror: ' + e.message))
p.on('console', (m) => { if (m.type() === 'error') erros.push('console: ' + m.text()) })
await p.goto('http://localhost:5174/')

const grupos = {
  rostos: (id) => id.startsWith('rosto_'),
  amigos_ferramentas_cenas: (id) => /^(amigo_|fer_|cena_)/.test(id),
  hiperfocos_personagens: (id) => id.startsWith('hf_'),
  itens_trem_aranha: (id) => /^item_(trem|aranha)_/.test(id),
  itens_aviao_dino: (id) => /^item_(aviao|dinossauro)_/.test(id),
  extras: (id) => /^(estrela|lesma|mola|nuvem|bandeira|gota|trofeu|p_|jogo_)/.test(id),
}
const resumo = await p.evaluate(async () => {
  const { ARTE } = await import('/src/arte/index.js')
  window.__ARTE = ARTE
  return { total: Object.keys(ARTE).length, quadros: Object.values(ARTE).reduce((s, a) => s + a.frames.length, 0) }
})
console.log('arte registrada:', resumo)

for (const [nome, filtro] of Object.entries(grupos)) {
  const ok = await p.evaluate((src) => {
    const f = eval(src)
    document.body.innerHTML = ''
    document.body.style.cssText = 'margin:0;padding:12px;background:#3a3f4b;font:11px sans-serif;color:#fff;display:flex;flex-wrap:wrap;gap:10px'
    let n = 0
    for (const [id, d] of Object.entries(window.__ARTE)) {
      if (!f(id)) continue
      const cel = document.createElement('div')
      cel.style.cssText = 'background:#59606f;border-radius:8px;padding:6px;text-align:center'
      const quadros = d.frames.map((svg) => `<img width="96" height="96" src="data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}">`).join('')
      cel.innerHTML = `<div style="display:flex;gap:2px">${quadros}</div>${id}`
      document.body.appendChild(cel); n++
    }
    return n
  }, filtro.toString())
  await new Promise((r) => setTimeout(r, 400))
  await p.screenshot({ path: `gal_${nome}.png`, fullPage: true })
  console.log(nome, ok, 'itens')
}
console.log('erros:', erros)
await b.close()

