// Converte os emojis dos dados em ids de arte. Uso: node converter.mjs <pasta app/src>
import { readFileSync, writeFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'
import { join } from 'node:path'

const src = process.argv[2]
const { ID_DE_EMOJI } = await import(pathToFileURL(join(src, 'arte/rostos.js')).href)
const semVariacao = (s) => s.replaceAll('️', '')
const CENAS = { '🍦': 'sorvete', '🌳': 'arvore', '🌙': 'lua', '🍽': 'prato', '⚽': 'bola', '🎁': 'presente', '🎲': 'dado', '🌛': 'lua', '🧸': 'ursinho', '🏫': 'escola', '🧩': 'quebra', '🚚': 'caminhao' }

function trocar(arquivo, regex, fn) {
  const caminho = join(src, 'data', arquivo)
  let n = 0
  const novo = readFileSync(caminho, 'utf8').replace(regex, (...m) => { n++; return fn(...m) })
  writeFileSync(caminho, novo)
  console.log(arquivo, regex.source.slice(0, 30), '->', n, 'trocas')
}

const naoMapeados = []
const cara = (_, emoji) => {
  const id = ID_DE_EMOJI[semVariacao(emoji)]
  if (!id) naoMapeados.push(emoji)
  return `cara: '${id}'`
}
trocar('situacoes.js', /cara: '([^']+)'/g, cara)
trocar('cuidados.js', /cara: '([^']+)'/g, cara)
trocar('cuidados.js', /cena: '([^']+)'/g, (_, e) => `cena: '${CENAS[semVariacao(e)]}'`)
trocar('cuidados.js', /^  (\w+): \{ emoji: '[^']+', nome: '([^']+)' \},$/gm, (_, id, nome) => `  ${id}: { arte: 'fer_${id}', nome: '${nome}' },`)
trocar('emocoes.js', /id: '(\w+)', nome: '([^']+)', emoji: '[^']+'/g, (_, id, nome) => `id: '${id}', nome: '${nome}', arte: 'rosto_${id}'`)
console.log('sem mapeamento:', naoMapeados)

