function trocar(arquivo, regex, fn) {
  const caminho = join(src, 'data', arquivo)
  let n = 0
  const novo = readFileSync(caminho, 'utf8').replace(regex, (...m) => { n++; return fn(...m) })
  writeFileSync(caminho, novo)
  console.log(arquivo, regex.source.slice(0, 30), '->', n, 'trocas')
