import puppeteer from 'puppeteer-core'
const b = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: true })
const p = await b.newPage()
await p.setViewport({ width: 1000, height: 800 })
const erros = []
p.on('pageerror', (e) => erros.push('pageerror: ' + e.message))
p.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') erros.push(`${m.type()}: ${m.text()}`) })
const esperar = (ms) => new Promise((r) => setTimeout(r, ms))
const clicar = async (txt) => { const [h] = await p.$$(`xpath/.//button[contains(., "${txt}")]`); if (!h) throw new Error('sem botão ' + txt); await h.click() }
const cena = (fn, ...a) => p.evaluate((src, ...args) => {
  const s = window.__phaser.scene.scenes.find((x) => x.ctx)
  return new Function('s', ...args.map((_, i) => 'a' + i), 'return (' + src + ')(s' + args.map((_, i) => ',a' + i).join('') + ')')(s, ...args)
}, fn.toString(), ...a)
const aguardarJogo = async () => { for (let i = 0; i < 60; i++) { if (await p.evaluate(() => !!window.__phaser?.scene.scenes.find((x) => x.ctx && x.sys.isActive()))) return; await esperar(250) } throw new Error('jogo não iniciou') }
const canvasBox = async () => (await p.$('canvas')).boundingBox()
const sair = async () => { const bb = await canvasBox(); await p.mouse.click(bb.x + bb.width * 0.925, bb.y + bb.height * 0.058); await esperar(500) }
const tela = (nome, clip) => p.screenshot({ path: `art_${nome}.png`, ...(clip ? { clip } : {}) })
const CLIP = { x: 60, y: 90, width: 880, height: 500 }

await p.goto('http://localhost:5174/')
await p.evaluate(() => localStorage.clear())
await p.reload()
await p.type('input', 'Lia')
await clicar('Preencher exemplo'); await clicar('Continuar')
await esperar(500)
await tela('hiperfocos')
await clicar('Trem')
await esperar(500)
await tela('menu')
const t0 = Date.now()
const titulos = await p.$$eval('.cartao h3', (hs) => hs.map((h) => h.innerText))
const abrir = async (nome) => { const i = titulos.findIndex((t) => t.includes(nome)); const bs = await p.$$('.cartao button'); await bs[i].click(); await aguardarJogo(); await esperar(900) }

// ---- Chuva
await abrir('Chuva')
console.log('arte carregada e jogo iniciado em', Date.now() - t0, 'ms')
await p.mouse.move(500, 600); await esperar(3500)
await tela('chuva', CLIP)
const sprites = await cena((s) => ({ jogador: s.jogador.arteId, itens: s.itens.length, alvo: s.alvo.arte }))
console.log('chuva:', sprites)
await sair()

// ---- Cuidar do amigo
await abrir('Cuidar')
await tela('cuidar', CLIP)
const info = await cena((s) => ({ sentimento: s.situacao.cara, itens: s.itens.map((i) => i.id), certos: s.situacao.certos }))
